D=open('/app/disk.img','rb').read()
bs=512; spc=4; reserved=4; fats=2; root_entries=512; fat_secs=32
root_off=(reserved+fats*fat_secs)*bs
data_off=(reserved+fats*fat_secs+(root_entries*32+bs-1)//bs)*bs
max_cluster=(len(D)-data_off)//(spc*bs)
print('data_off',hex(data_off),'max_cluster',max_cluster)

def plausible(attr,start,size):
    return ((attr & 0xC0)==0) and attr!=0x0F and attr!=0x08 and (start in range(2,max_cluster+2)) and (size in range(0,20000000))

c=[]
for i in range(root_entries):
    e=D[root_off+i*32:root_off+i*32+32]
    if len(e)==32 and e[0]==0xE5 and plausible(e[11],int.from_bytes(e[26:28],'little'),int.from_bytes(e[28:32],'little')):
        c.append(('ROOT',i,e,int.from_bytes(e[26:28],'little'),int.from_bytes(e[28:32],'little')))
for clu in range(2,max_cluster+2):
    base=data_off+(clu-2)*spc*bs
    for i in range((spc*bs)//32):
        e=D[base+i*32:base+i*32+32]
        if e[0]==0xE5 and plausible(e[11],int.from_bytes(e[26:28],'little'),int.from_bytes(e[28:32],'little')):
            c.append((str(clu),i,e,int.from_bytes(e[26:28],'little'),int.from_bytes(e[28:32],'little')))
print('plausible deleted entry candidates:',len(c))
for loc,i,e,start,size in c:
    print('loc',loc,'idx',i,'name',e[:11],'attr',hex(e[11]),'start',start,'size',size,'raw',e.hex())
